$photos=['before'=>[],'after'=>[]]; $stmt=$mysqli->prepare('SELECT photo_type,file_path FROM bad_photos WHERE bad_id=? ORDER BY photo_type,sort_order,id'); $stmt->bind_param('i',$id); $stmt->execute(); $res=$stmt->get_result(); while($p=$res->fetch_assoc()) $photos[$p['photo_type']][]=$p['file_path'];
